from qiskit import QuantumCircuit, ClassicalRegister
from typing import Callable

def _zval(idx, m0, m1):
    return [(-1) ** m1, (-1) ** m0, (-1) ** (m0 ^ m1)][idx]
_ROW_CIRCUITS = {0: [], 1: [('H', 0), ('H', 1)], 2: [('H', 0), ('CX', (0, 1)), ('H', 0)]}
_COL_CIRCUITS = {0: [('H', 0)], 1: [('H', 1)], 2: [('CX', (0, 1)), ('H', 0)]}
_ROW_DECODE = {0: [(0, +1), (1, +1), (2, +1)], 1: [(1, +1), (0, +1), (2, +1)], 2: [(0, -1), (1, -1), (2, +1)]}
_COL_DECODE = {0: [(0, +1), (1, +1), (2, -1)], 1: [(1, +1), (0, +1), (2, -1)], 2: [(0, +1), (1, +1), (2, -1)]}

def _append_circuit(qc, ops, qs):
    for name, arg in ops:
        if name == 'H':
            qc.h(qs[arg])
        elif name == 'CX':
            qc.cx(qs[arg[0]], qs[arg[1]])

